import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, SessionRateLimit, SessionUsage, Timer } from 'claude-code'

import type { Branch, Tally, Usage } from '../types'
import { bar, modelName, pct, ratio, resetClock, resetDate, tokens, usd } from './format'
import { BRANCH_SPRITE, pack, pixelText, pixelWidth } from './pixel'

const branch = atom({ plugin: 'pixel-hud', key: 'branch' } as const, null)
const usage = atom({ plugin: 'pixel-hud', key: 'usage' } as const, null)
const EMPTY: Tally = { effort: null, sent: 0, cacheRead: 0, out: 0, thinkChars: 0, textChars: 0 }
const tally = atom({ plugin: 'pixel-hud', key: 'tally' } as const, EMPTY)

// Branch: NES-style palette, a vertical title gradient, green sprite, red alert.
const ROW_COLORS = ['#58f898', '#3cbcfc', '#6888fc']
const SPRITE_COLOR = '#00b800'
const DIRTY_COLOR = '#f83800'
const SPRITE = pack(BRANCH_SPRITE)
const GAP = '  '
// Meter: Pico-8-ish palette.
const PINK = '#ff4f9a'
const GREEN = '#5fe08a'
const RED = '#ff5f5f'
const INK = '#e6e6e6'
const CHIP_TEXT = '#1a1a24'
const STAR = ' ★ '
// Big glyphs (3 rows) plus the meter (2 rows).
const FULL_ROWS = 5
// /clear empties $.state and raises no session.start, and a branch switched
// outside Claude Code raises no event: poll to catch both.
const POLL_MS = 3000

async function loadBranch($: EngineInterface) {
  const head = await $.process.run(['git', 'rev-parse', '--abbrev-ref', 'HEAD'])
  if (head.exitCode !== 0) {
    await update($, branch, () => null)
    return
  }
  const status = await $.process.run(['git', 'status', '--porcelain'])
  const next: Branch = { name: head.stdout.trim(), isDirty: status.stdout.trim() !== '' }
  await update($, branch, prev =>
    prev?.name === next.name && prev.isDirty === next.isDirty ? prev : next,
  )
}

function windowOf(limits: readonly SessionRateLimit[], kind: string): Usage['fiveHour'] {
  const w = limits.find(l => l.kind === kind)
  return w ? { percent: w.percentUsed, resetsAt: w.resetsAt } : null
}

function toUsage(model: string, u: Pick<SessionUsage, 'context' | 'rateLimits' | 'cost'>): Usage {
  return {
    model,
    ctxPercent: u.context.percent ?? null,
    fiveHour: windowOf(u.rateLimits, 'five_hour'),
    sevenDay: windowOf(u.rateLimits, 'seven_day'),
    usd: u.cost?.usd ?? null,
  }
}

async function loadUsage($: EngineInterface) {
  const [model, u] = await Promise.all([$.session.model(), $.session.usage()])
  await update($, usage, () => toUsage(model, u))
}

async function refresh($: EngineInterface) {
  await Promise.all([
    loadBranch($).catch(() => update($, branch, () => null)),
    // Keep the last reading; the next poll or measure tries again.
    loadUsage($).catch(() => undefined),
  ])
}

// How many glyphs of the name fit beside the sprite and the dirty mark.
function fitName(name: string, isDirty: boolean, columns: number): string | null {
  const fixed = (BRANCH_SPRITE[0] ?? '').length + GAP.length + (isDirty ? GAP.length + pixelWidth(1) : 0)
  const room = Math.floor((columns - fixed + 1) / 4)
  if (room < 4) {
    return null
  }
  return name.length <= room ? name : `${name.slice(0, room - 2)}..`
}

export const register: Register = on => {
  let poll: Timer | undefined

  on('session.start', async ($, e, next) => {
    await refresh($)
    poll?.cancel()
    poll = $.clock.every(POLL_MS, () => void refresh($))
    return next(e)
  })

  on('session.end', async ($, e, next) => {
    const result = await next(e)
    if (e.reason === 'clear') {
      $.clock.after(200, () => void refresh($))
    }
    return result
  })

  on('session.measure', async ($, e, next) => {
    const model = await $.session.model()
    await update($, usage, () => toUsage(model, e))
    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    const result = await next(e)
    if (e.tool === 'Bash' || e.tool === 'Edit' || e.tool === 'Write') {
      await loadBranch($).catch(() => update($, branch, () => null))
    }
    return result
  }).catch(($, e, next) => next(e))

  on('turn.step', async function* ($, e, next) {
    let thinkChars = 0
    let textChars = 0
    const stream = next(e)
    for await (const chunk of stream) {
      if (chunk.kind === 'thinking') thinkChars += chunk.text.length
      else if (chunk.kind === 'text') textChars += chunk.text.length
      yield chunk
    }
    const result = await stream.result
    const u = result.usage
    await update($, tally, prev => {
      const t = prev ?? EMPTY
      return {
        effort: e.agentId || e.effort === undefined ? t.effort : String(e.effort),
        sent: t.sent + (u ? u.input_tokens + u.cache_read_input_tokens + u.cache_creation_input_tokens : 0),
        cacheRead: t.cacheRead + (u?.cache_read_input_tokens ?? 0),
        out: t.out + (u?.output_tokens ?? 0),
        thinkChars: t.thinkChars + thinkChars,
        textChars: t.textChars + textChars,
      }
    })
    return result
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const git = await read($, branch)
    const now = await read($, usage)
    if (e.props.hasSurvey || (git === null && now === null)) {
      return next(e)
    }
    const t = (await read($, tally)) ?? EMPTY
    const { Box, Text } = $.ui.resolve(e)

    // Branch: big glyphs when there is room, else a chunky chip.
    const name = git && e.props.maxRows >= FULL_ROWS ? fitName(git.name, git.isDirty, e.props.bodyColumns) : null
    const glyphs = name === null ? null : pixelText(name)
    const dirty = pixelText('*')
    const chip =
      git && glyphs === null
        ? [
            <Text key="chip" color="#fcfcfc" backgroundColor="#0058f8" bold>
              {` ▶ ${git.name.toUpperCase()} `}
            </Text>,
            git.isDirty ? (
              <Text key="chip-dirty" color="#fcfcfc" backgroundColor={DIRTY_COLOR} bold>
                {' ! '}
              </Text>
            ) : null,
            <Text key="chip-gap"> </Text>,
          ]
        : null

    const star = (key: string) => (
      <Text key={key} dimColor>
        {STAR}
      </Text>
    )
    const label = (key: string, text: string) => (
      <Text key={key} color={PINK}>
        {text}
      </Text>
    )
    const meter = (key: string, percent: number) => (
      <Text key={key} color={percent >= 90 ? RED : GREEN}>
        {` ${bar(percent)} ${pct(percent)}`}
      </Text>
    )
    const when = (key: string, text: string | null) =>
      text ? (
        <Text key={key} dimColor>
          {` (${text})`}
        </Text>
      ) : null

    const cacheRate = ratio(t.cacheRead, t.sent)
    const thinkRate = ratio(t.thinkChars, t.thinkChars + t.textChars)

    return (
      <Box flexDirection="column">
        {glyphs && git
          ? glyphs.map((line, row) => (
              <Box key={`row-${row}`}>
                <Text color={SPRITE_COLOR}>{SPRITE[row]}</Text>
                <Text>{GAP}</Text>
                <Text color={ROW_COLORS[row]} bold>
                  {line}
                </Text>
                {git.isDirty ? <Text color={DIRTY_COLOR}>{GAP + dirty[row]}</Text> : null}
              </Box>
            ))
          : null}
        {now ? (
          <Box key="meter" flexWrap="wrap">
            {chip}
            <Text color={CHIP_TEXT} backgroundColor={PINK} bold>
              {` ${modelName(now.model)} `}
            </Text>
            {t.effort ? <Text color={INK}>{`:${t.effort}`}</Text> : null}
            {now.ctxPercent !== null ? [star('s1'), label('l1', 'CTX'), meter('m1', now.ctxPercent)] : null}
            {now.fiveHour
              ? [star('s2'), label('l2', '5H'), meter('m2', now.fiveHour.percent), when('w2', resetClock(now.fiveHour.resetsAt))]
              : null}
            {now.sevenDay
              ? [star('s3'), label('l3', '7D'), meter('m3', now.sevenDay.percent), when('w3', resetDate(now.sevenDay.resetsAt))]
              : null}
            {now.usd !== null ? [star('s4'), <Text key="usd" color={INK}>{usd(now.usd)}</Text>] : null}
          </Box>
        ) : (
          <Box key="chip-only">{chip}</Box>
        )}
        {now ? (
          <Box key="tally">
            {label('sent', 'SENT')}
            <Text color={INK}>{` ${tokens(t.sent)} `}</Text>
            {label('cr', 'CR')}
            <Text color={INK}>{` ${cacheRate === null ? '--' : pct(cacheRate)}`}</Text>
            {star('s5')}
            {label('out', 'OUT')}
            <Text color={INK}>{` ${tokens(t.out)} `}</Text>
            {label('th', 'TH')}
            <Text color={INK}>{` ${thinkRate === null ? '--' : pct(thinkRate)}`}</Text>
          </Box>
        ) : null}
      </Box>
    )
  })
}

