// Pure formatting for the meter: bars, token counts, reset times, model chip.

const BAR_CELLS = 5

export function bar(percent: number): string {
  const filled = Math.max(0, Math.min(BAR_CELLS, Math.round((percent / 100) * BAR_CELLS)))
  return '▰'.repeat(filled) + '▱'.repeat(BAR_CELLS - filled)
}

export function pct(value: number): string {
  return `${Math.round(value)}%`
}

export function tokens(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}k`
  return String(n)
}

export function usd(n: number): string {
  return `$${n.toFixed(2)}`
}

const pad = (n: number) => String(n).padStart(2, '0')

// 5h window: the local clock time it resets at.
export function resetClock(iso: string | undefined): string | null {
  const at = iso ? new Date(iso) : null
  return at && !Number.isNaN(at.getTime()) ? `${pad(at.getHours())}:${pad(at.getMinutes())}` : null
}

// 7d window: the local date it resets on.
export function resetDate(iso: string | undefined): string | null {
  const at = iso ? new Date(iso) : null
  return at && !Number.isNaN(at.getTime()) ? `${pad(at.getMonth() + 1)}/${pad(at.getDate())}` : null
}

const FAMILIES = ['opus', 'sonnet', 'haiku', 'fable']

export function modelName(model: string): string {
  const lower = model.toLowerCase()
  const family = FAMILIES.find(f => lower.includes(f))
  return family ? family.charAt(0).toUpperCase() + family.slice(1) : model
}

export function ratio(part: number, whole: number): number | null {
  return whole > 0 ? (part / whole) * 100 : null
}

