export type Branch = { name: string; isDirty: boolean }

export type Usage = {
  model: string
  ctxPercent: number | null
  fiveHour: { percent: number; resetsAt?: string } | null
  sevenDay: { percent: number; resetsAt?: string } | null
  usd: number | null
}

export type Tally = {
  effort: string | null
  sent: number
  cacheRead: number
  out: number
  thinkChars: number
  textChars: number
}

declare module 'claude-code' {
  interface PluginState {
    'pixel-hud': { branch: Branch | null; usage: Usage | null; tally: Tally }
  }
}
